changeSet.sql:
CREATE TABLE scenario_watches (
	id SERIAL NOT NULL,
	user_id INTEGER NOT NULL,
	snapshot_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (user_id, snapshot_id),
	FOREIGN KEY(user_id) REFERENCES users (id),
	FOREIGN KEY(snapshot_id) REFERENCES scenario_snapshots (id)
);
CREATE INDEX ix_scenario_watches_snapshot_id ON scenario_watches (snapshot_id);
CREATE INDEX ix_scenario_watches_user_id ON scenario_watches (user_id);
